1820|export function collectTaskFiles({ workdir, taskId, docsDirName = null, project = null, docsWorkdir = null } = {}) {
1821|	const resolved = resolveRunnerDocsDirName(
1822|		docsDirName ?? (typeof project === "object" && project !== null ? project : null),
1823|	);
1824|	// With a separate docs repo the task docs live in the paired docs
1825|	// worktree (synced through git), not in the code worktree.
1826|	const base = docsWorkdir || workdir;
1827|	const dir = path.join(base, resolved, "tasks", taskId);
1828|	const files = [];
1829|	let total = 0;
1830|	try {
1831|		for (const name of fs.readdirSync(dir)) {
1832|			if (name === "task.md") continue;
1833|			try {
1834|				const content = fs.readFileSync(path.join(dir, name), "utf8");
1835|				const bytes = Buffer.byteLength(content, "utf8");
1836|				if (bytes > 256 * 1024 || total + bytes > 1024 * 1024) continue;
1837|				files.push({ name, content });
1838|				total += bytes;
1839|			} catch { /* unreadable/binary: skip */ }
1840|		}
1841|	} catch { /* no task docs: nothing to ship */ }
1842|	return files;
